<script setup>
import {ref,onMounted,computed} from 'vue'
import {api} from '../lib/api'
import {syncCurriculum} from '../data/quiz'
import ManualProblemEditor from './ManualProblemEditor.vue'
const emit=defineEmits(['updated']),catalog=ref([]),subject=ref('vue'),subjectName=ref(''),unitName=ref(''),error=ref(''),notice=ref(''),busy=ref(false),editing=ref(null),editor=ref(false),posts=ref([]),editorKey=ref(0)
const management=ref(null),manageAction=ref('delete'),confirmName=ref(''),target=ref(''),allSubjects=ref([])
const selected=computed(()=>allSubjects.value.find(s=>s.id===subject.value))
function openManage(action){manageAction.value=action;confirmName.value='';target.value='';management.value.showModal()}
async function manage(){if(busy.value)return;busy.value=true;error.value='';try{await api('/admin/curriculum',{method:'PATCH',body:{action:manageAction.value,subject:subject.value,target:target.value,confirmName:confirmName.value}});management.value.close();editor.value=false;await load();notice.value=manageAction.value==='move'?'단원과 문제를 이동했어요. 기록과 공개 진도는 유지됩니다.':manageAction.value==='restore'?'과목을 복구했어요.':'과목을 삭제했어요. 삭제한 과목에서 복구할 수 있어요.';subject.value=catalog.value[0]?.id??'';emit('updated')}catch(e){error.value=e.message}finally{busy.value=false}}
const units=computed(()=>catalog.value.find(s=>s.id===subject.value)?.units??[])
async function load(){allSubjects.value=await api('/admin/curriculum');catalog.value=allSubjects.value.filter(s=>!s.archived);syncCurriculum(catalog.value);posts.value=(await api('/workshop')).items.filter(p=>p.source==='official')}
async function add(kind){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/admin/curriculum',{method:'POST',body:{kind,name:kind==='subject'?subjectName.value:unitName.value,subject:subject.value}});await load();if(kind==='subject')subject.value=result.id;subjectName.value='';unitName.value='';notice.value='등록했어요. 새 단원은 기수별 진도 공개 후 학습할 수 있습니다.';emit('updated')}catch(e){error.value=e.message}finally{busy.value=false}}
function create(){editing.value=null;editorKey.value++;editor.value=true}
async function edit(id){error.value='';try{editing.value=await api('/workshop/'+id+'/edit');editorKey.value++;editor.value=true}catch(e){error.value=e.message}}
async function saved(){editor.value=false;notice.value='공식 문제를 저장했어요.';await load();emit('updated')}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section class="panel admin-content"><div class="mailbox-heading"><h2>과목·단원 / 공식 문제 관리</h2><button @click="create">＋ 공식 문제 추가</button></div><p>등록한 과목·단원은 학생 문제 제작 드롭다운과 기수별 진도 공개에 함께 표시됩니다.</p><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="content-settings"><form @submit.prevent="add('subject')"><label>새 과목 이름<input v-model="subjectName" maxlength="100" required placeholder="예: Java"/></label><button :disabled="busy">과목 추가</button></form><form @submit.prevent="add('unit')"><label>과목<select v-model="subject"><option v-for="s in catalog" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>새 단원 이름<input v-model="unitName" maxlength="100" required placeholder="예: 객체와 클래스"/></label><button :disabled="busy">단원 추가</button></form></div><div class="toolbar"><button class="light" :disabled="busy||!selected" @click="openManage('delete')">선택 과목 삭제</button><button class="light" :disabled="busy||!selected" @click="openManage('move')">선택 과목 이동</button></div><p>이동하면 해당 과목의 단원·문제를 대상 과목으로 합치고 원래 과목은 목록에서 숨깁니다. 문제 ID와 기존 기록은 유지됩니다.</p><details><summary>삭제한 과목 · 복구</summary><div v-for="s in allSubjects.filter(s=>s.archived)" :key="s.id" class="toolbar"><b>{{s.name}}</b><button :disabled="busy" @click="subject=s.id;openManage('restore')">복구</button></div></details><dialog ref="management" aria-label="과목 관리 확인"><h2>{{manageAction==='move'?'과목 이동':manageAction==='restore'?'과목 복구':'과목 삭제'}}</h2><p><b>{{selected?.name}}</b> 과목을 {{manageAction==='move'?'다른 과목으로 이동':manageAction==='restore'?'복구':'학생 화면과 드롭다운에서 삭제'}}합니다. 기존 학습·포인트 기록은 보존됩니다.</p><label v-if="manageAction==='move'">이동할 대상 과목<select v-model="target"><option value="">대상 선택</option><option v-for="s in catalog.filter(s=>s.id!==subject)" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>확인을 위해 과목 이름 입력<input v-model="confirmName" :placeholder="selected?.name"/></label><p v-if="error" role="alert">{{error}}</p><div class="toolbar"><button class="light" :disabled="busy" @click="management.close()">취소</button><button :disabled="busy||confirmName!==selected?.name||(manageAction==='move'&&!target)" @click="manage">{{busy?'처리 중…':'확인'}}</button></div></dialog><p>{{units.map(u=>u.title).join(' / ')||'단원을 추가하세요.'}}</p><ManualProblemEditor v-if="editor" :key="editorKey" :initial="editing" :admin="true" :catalog="catalog" @saved="saved" @cancel="editor=false"/><details v-else><summary>추가한 공식 문제 {{posts.length}}개</summary><article v-for="p in posts" :key="p.id" class="content-post"><span><b>{{p.title}}</b> · {{p.published?'공개 중':'비공개'}}</span><button class="light" @click="edit(p.id)">공식 문제 수정</button></article></details></section></template>
